import React, { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import AuthContext from '../context/AuthContext';

function Jobs() {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const { user } = useContext(AuthContext);

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    try {
      const res = await axios.get('http://localhost:5001/api/jobs', { withCredentials: true });
      setJobs(res.data.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleApply = (jobId) => {
    navigate(`/upload?jobId=${jobId}`);
  };

  return (
    <div className="page mt-0">
      <section className="bg-slate-50 pt-16 pb-12 border-b border-border-light">
        <div className="container">
          <div className="flex justify-between items-end">
            <div>
              <h1 className="text-2xl mb-2">Carrier <span className="text-accent">Opportunities</span></h1>
              <p className="muted">Explore high-impact roles analyzed by our match intelligence.</p>
            </div>
            {user && (user.role === 'recruiter' || user.role === 'admin') && (
              <button className="btn btn-primary" onClick={() => navigate('/create-job')}>
                Establish Requisition
              </button>
            )}
          </div>
        </div>
      </section>

      <div className="container py-16">
        {loading ? (
          <div className="text-center py-20">
            <p className="muted animate-pulse font-bold tracking-widest uppercase text-[10px]">Scanning requisition database...</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {jobs.length === 0 ? (
              <div className="col-span-full card text-center py-20">
                <p className="muted">No active requisitions found.</p>
              </div>
            ) : jobs.map(job => (
              <div className="card flex flex-col group" key={job._id} style={{ padding: '32px' }}>
                <div className="mb-6 flex-1">
                  <span className="text-[10px] text-accent font-black uppercase tracking-widest mb-3 block">High Priority</span>
                  <h3 className="text-lg font-black mb-3 group-hover:text-accent transition-colors">{job.title}</h3>
                  <p className="small muted line-clamp-3 mb-6" style={{ height: '4.5em' }}>{job.description}</p>

                  <div className="pt-6 border-t border-border-light">
                    <span className="block text-[10px] muted uppercase font-black mb-3">Target Competencies</span>
                    <div className="flex flex-wrap gap-2">
                      {job.requiredSkills.map((skill, i) => (
                        <span key={i} className="chip" style={{ fontSize: '11px', padding: '6px 12px' }}>{skill}</span>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="space-y-3 pt-6">
                  <button className="btn btn-primary w-full" onClick={() => handleApply(job._id)}>
                    Apply Now
                  </button>

                  {user && (user.role === 'recruiter' || user.role === 'admin') && (
                    <button className="btn btn-ghost w-full" onClick={() => navigate(`/history?jobId=${job._id}`)}>
                      Review Applicants
                    </button>
                  )}
                </div>

                <div className="mt-8 flex justify-between items-center pt-6 border-t border-border-light text-[10px] muted font-black uppercase tracking-tighter">
                  <div className="flex items-center gap-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-success" />
                    Remote Available
                  </div>
                  <span>Ref: {job._id?.slice(-6).toUpperCase()}</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default Jobs;
